procedure ClauseSpaceSearch(F, s):
    queue <- {(empty, [empty])}
    visited <- {empty}
    while queue not empty:
        (C, trace) <- dequeue(queue)
        if contradiction in C: return trace
        for each legal move (download/resolve/erase):
            C' <- apply_move(C)
            if |C'| <= s and C' not in visited:
                visited <- visited + {C'}
                enqueue(queue, (C', trace + [C']))
    return failure
